@RestController
@CrossOrigin(exposedHeaders = "errors, content-type")
@RequestMapping("/api")
public class OwnerRestControllerV1 implements OwnersApi {

    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");

    private final ClinicService clinicService;

    private final OwnerMapper ownerMapper;

    private final PetMapper petMapper;

    private final VisitMapper visitMapper;

    private final IdempotencyKeyRegistry idempotencyKeyRegistry;

    private final OwnerAuditEventPublisher auditEventPublisher;

    public OwnerRestControllerV1(ClinicService clinicService,
                                 OwnerMapper ownerMapper,
                                 PetMapper petMapper,
                                 VisitMapper visitMapper,
                                 IdempotencyKeyRegistry idempotencyKeyRegistry,
                                 OwnerAuditEventPublisher auditEventPublisher) {
        this.clinicService = clinicService;
        this.ownerMapper = ownerMapper;
        this.petMapper = petMapper;
        this.visitMapper = visitMapper;
        this.idempotencyKeyRegistry = idempotencyKeyRegistry;
        this.auditEventPublisher = auditEventPublisher;
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
        Collection<Owner> owners;
        if (lastName != null) {
            owners = this.clinicService.findOwnerByLastName(lastName);
        } else {
            owners = this.clinicService.findAllOwners();
        }
        if (owners.isEmpty()) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        return new ResponseEntity<>(toOwnerDtoWithWarning(owner), HttpStatus.OK);
    }

    /** Map an owner to its DTO, setting the read-only {@code bulkSignupWarning} and
     *  {@code capacityWarning} flags the same way for every owner response. */
    private OwnerDto toOwnerDtoWithWarning(Owner owner) {
        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
        ownerDto.setBulkSignupWarning(this.clinicService.isBulkSignupDay());
        ownerDto.setCapacityWarning(this.clinicService.isCityApproachingCapacity(owner.getCity()));
        return ownerDto;
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
        // A create retried with an already-seen idempotency key returns the originally created
        // owner with 200, rather than creating a duplicate.
        Integer existingId = this.idempotencyKeyRegistry.findOwnerId(idempotencyKey).orElse(null);
        if (existingId != null) {
            Owner existing = this.clinicService.findOwnerById(existingId);
            if (existing != null) {
                return new ResponseEntity<>(toOwnerDtoWithWarning(existing), HttpStatus.OK);
            }
        }
        HttpHeaders headers = new HttpHeaders();
        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
        AddressValidator.validate(owner.getAddress());
        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
        DisposableEmailValidator.validate(owner.getEmail());
        RegistrationDateValidator.validate(owner.getRegistrationDate());
        if (this.clinicService.isDailyRegistrationAtCapacity()) {
            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
        }
        // The household id is deterministic from (lastName, postcode), so owners sharing a last name
        // and postcode are automatically the same household. It no longer gates duplicate detection
        // (that is the identity key alone) but still drives household-derived fields.
        owner.setHouseholdId(this.clinicService.householdIdFor(owner.getLastName(), owner.getPostcode()));
        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
        // Duplicate detection is the single identity key: reject only when the new owner's whole
        // identity key (SHA-256 over normalizedTelephone|lowerEmail|soundex(lastName)) matches an
        // existing, non-deleted owner's. Two owners with the same last name and postcode but different
        // telephones have distinct keys and are created as a soft match rather than rejected.
        if (this.clinicService.isIdentityKeyInUse(owner)) {
            return new ResponseEntity<>(HttpStatus.CONFLICT);
        }
        if (this.clinicService.isCityAtCapacity(owner.getCity())) {
            return new ResponseEntity<>(HttpStatus.CONFLICT);
        }
        this.clinicService.saveOwner(owner, sharesHousehold);
        this.idempotencyKeyRegistry.remember(idempotencyKey, owner.getId());
        AUDIT.info("owner created: id={} memberId={} registrationDate={} membershipLevel={}",
            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
            ownerMapper.formatMembershipLevel(owner));
        this.auditEventPublisher.ownerCreated(owner, ownerMapper.formatMembershipLevel(owner));
        OwnerDto ownerDto = toOwnerDtoWithWarning(owner);
        headers.setLocation(UriComponentsBuilder.newInstance()
            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
        if (currentOwner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        PostcodeValidator.validate(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
        DisposableEmailValidator.validate(ownerMapper.normalizeEmail(ownerFieldsDto.getEmail()));
        ownerMapper.applyAddressFields(ownerFieldsDto, currentOwner);
        AddressValidator.validate(currentOwner.getAddress());

